constraints:
1 <= N <= 10^{8}

expected time complexity: O(sqrt(N))
expected auxiliary space: O(1)

standard_solution_code:
class Solution:

	def getCount(self, N):
		c = 0
		l = 1
		while l * (l + 1) < 2 * N:
			a = (1.0 * N - l * (l + 1) / 2) / (l + 1)
			if a - int(a) == 0.0:
				c += 1
			l += 1
		return c
